issue.body:
### What happened?

`cursor.execute` treats non-dict parameters as sequences and calls `PySequence_Size`, so a crafted object can close the connection inside `__len__` and clear `self->connection->db`. The cursor continues using that null handle and eventually calls `sqlite3_last_insert_rowid`, which dereferences the null connection pointer and crashes.

**Proof of Concept:**

```python
import sqlite3

class Seq:
    def __init__(self, conn):
        self.conn = conn

    def __len__(self):
        self.conn.close()
        return 1

    def __getitem__(self, i):
        if i:
            raise IndexError
        return 42


conn = sqlite3.connect(":memory:")
conn.cursor().execute("SELECT ?", Seq(conn))
```

**Vulnerable Code Snippet:**

<details>
<summary>Click to expand</summary>

```c
/* Buggy Re-entrant Path */
static PyObject *
pysqlite_cursor_execute_impl(pysqlite_Cursor *self, PyObject *sql,
                             PyObject *parameters)
{
    return _pysqlite_query_execute(self, 0, sql, parameters);
}

static void
bind_parameters(pysqlite_state *state, pysqlite_Statement *self,
                PyObject *parameters)
{
    Py_ssize_t num_params;

    /* ... */

    if (PyTuple_CheckExact(parameters) || PyList_CheckExact(parameters) ||
        (!PyDict_Check(parameters) && PySequence_Check(parameters))) {
        /* parameters passed as sequence */
        if (PyTuple_CheckExact(parameters)) {
            num_params = PyTuple_GET_SIZE(parameters);
        } else if (PyList_CheckExact(parameters)) {
            num_params = PyList_GET_SIZE(parameters);
        } else {
            num_params = PySequence_Size(parameters);  /* Reentrant call site */
            if (num_params == -1) {
                return;
            }
        }
        /* ... */
    }
    /* ... */
}

PyObject *
_pysqlite_query_execute(pysqlite_Cursor* self, int multiple,
                        PyObject* operation, PyObject* second_argument)
{
    PyObject* parameters_iter = NULL;
    PyObject* parameters = NULL;

    /* ... */

    while (1) {
        parameters = PyIter_Next(parameters_iter);
        if (!parameters) {
            break;
        }

        bind_parameters(state, self->statement, parameters);

        /* ... */
    }

    if (!multiple) {
        sqlite_int64 lastrowid;

        Py_BEGIN_ALLOW_THREADS
        /* crashing pointer derived: self->connection->db */
        lastrowid = sqlite3_last_insert_rowid(self->connection->db);  /* Crash site */
        Py_END_ALLOW_THREADS

        Py_SETREF(self->lastrowid, PyLong_FromLongLong(lastrowid));
    }
    /* ... */
}

/* Clobbering Path */
static PyObject *
pysqlite_connection_close_impl(pysqlite_Connection *self)
{
    /* ... */
    Py_CLEAR(self->statement_cache);  /* state mutate site */
    if (connection_close(self) < 0) {
        return NULL;
    }

    Py_RETURN_NONE;
}

static int
connection_close(pysqlite_Connection *self)
{
    if (self->db == NULL) {
        return 0;
    }

    sqlite3 *db = self->db;
    self->db = NULL;  /* state mutate site */

    /* ... */
    return 0;
}
```
</details>

